 src=[idx[i] for i in a['source_ids']];tar=[idx[i] for i in a['target_ids']];out=set(W[src].nonzero()[1]);incoming=set(W[:,tar].nonzero()[0]);keep=src+tar+sorted((out&incoming)-set(src+tar));meta=[rows[i] for i in keep];mat=W[keep][:,keep];sparse.save_npz(O/(a['id']+'-connectivity.npz'),mat);(O/(a['id']+'-neurons.json')).write_text(json.dumps(meta,indent=2));a.update({'nodes':len(keep),'edges':mat.nnz,'context':'all direct and two-hop source-target paths, induced edges among retained nodes; missing external inputs and recurrent context','source_current_annotations':[rows[i] for i in src],'target_current_annotations':[rows[i] for i in tar],'direct_signed_weights':W[src][:,tar].toarray().tolist()})
